-- v10: Facebook

UPDATE properties SET value_cs = 'https://www.facebook.com/profile.php?id=100063858848240' WHERE pkey = 'site.facebook' AND value_cs = '';
UPDATE properties SET value_cs = REPLACE(value_cs, '<h2>Vaše práva</h2>', '<p>Příspěvky z Facebooku na úvodní stránce se načtou až po vašem kliknutí. Teprve potom společnost Meta Platforms Ireland Ltd. získá vaši IP adresu a může ukládat cookies podle svých <a href="https://www.facebook.com/privacy/policy/" target="_blank" rel="noopener">zásad ochrany soukromí</a>.</p><h2>Vaše práva</h2>'), value_en = REPLACE(value_en, '<h2>Your rights</h2>', '<p>Facebook posts on the home page load only after you click. Only then does Meta Platforms Ireland Ltd. receive your IP address and may set cookies under its <a href="https://www.facebook.com/privacy/policy/" target="_blank" rel="noopener">privacy policy</a>.</p><h2>Your rights</h2>') WHERE pkey = 'privacy.body' AND value_cs NOT LIKE '%Facebooku na úvodní stránce%';

-- v11: příspěvky z Facebooku přes Graph API

-- v12: faktury, Google Analytics, lišta cookies

UPDATE properties SET value_cs = REPLACE(value_cs, 'Analytické ani reklamní cookies nepoužíváme, proto se souhlas s cookies nevyžaduje.', 'Analytické cookies (Google Analytics) použijeme jen s vaším souhlasem, který udělíte nebo odmítnete v liště „Cookies“ a kdykoli změníte odkazem „Nastavení cookies“ v patičce. Google Analytics provozuje Google Ireland Ltd.; údaje mohou být předány do USA na základě rámce EU–USA pro ochranu osobních údajů. Reklamní cookies nepoužíváme.'), value_en = REPLACE(value_en, 'We use no analytics or advertising cookies, so no cookie consent is required.', 'We use analytics cookies (Google Analytics) only with your consent, which you give or refuse in the “Cookies” bar and can change at any time via “Cookie settings” in the footer. Google Analytics is operated by Google Ireland Ltd.; data may be transferred to the USA under the EU–US Data Privacy Framework. We use no advertising cookies.') WHERE pkey = 'privacy.body';

-- v13: odkaz zákazníka, reCAPTCHA, SMTP

UPDATE properties SET value_cs = REPLACE(value_cs, '<h2>Vaše práva</h2>', '<p>Formuláře chrání služba <strong>reCAPTCHA v3</strong> společnosti Google Ireland Ltd., která pomocí údajů o používání stránky (IP adresa, údaje o prohlížeči, pohyb na stránce) rozpozná automatizované odesílání. Načte se až ve chvíli, kdy začnete formulář vyplňovat. Právní základ: oprávněný zájem na ochraně před spamem (čl. 6 odst. 1 písm. f) GDPR).</p><h2>Vaše práva</h2>'), value_en = REPLACE(value_en, '<h2>Your rights</h2>', '<p>Our forms are protected by <strong>reCAPTCHA v3</strong> from Google Ireland Ltd., which uses usage data (IP address, browser data, interaction with the page) to detect automated submissions. It loads only when you start filling in a form. Legal basis: legitimate interest in protection against spam (Art. 6(1)(f) GDPR).</p><h2>Your rights</h2>') WHERE pkey = 'privacy.body' AND value_cs NOT LIKE '%reCAPTCHA%';

